def enrich(units, material_factory, evidence_factory):
    assert len(units)==len(SPECS)
    for u,s in zip(units,SPECS):
        title,extra,prompt,answer,quote,criteria=s
        challenge=material_factory(u,extra)
        q=dict(id=u['id']+'-Q7',kind='explanation',prompt=prompt,expectedAnswer=answer,
               evidence=[evidence_factory(challenge,quote)],hints=[],
               rubric=[dict(criterion=c,levels={'0':'해당 조건을 놓치거나 자료와 모순됨','1':'조건 일부만 반영하거나 판단 연결이 불완전함','2':answer}) for c in criteria])
        u['difficultyLevels']=[
          dict(id='supported',label='도움',materialId=u['material']['id'],supports=['핵심어 풀이','근거 구절 탐색','Q1~Q3 단계별 힌트'],questionIds=[x['id'] for x in u['questions'][:3]],recordAs='guided'),
          dict(id='standard',label='기본',materialId=u['material']['id'],supports=[],questionIds=[x['id'] for x in u['questions']],recordAs='practice'),
          dict(id='challenge',label='도전',materialId=challenge['id'],supports=[],questionIds=[q['id']],recordAs='practice')]
        u['challenge']=dict(title=title,material=challenge,question=q)
